var createFetchClient = (ServiceClient, connection) => {
  if (ServiceClient.Client) {
    ServiceClient = ServiceClient.Client;
  }
  const writeCb = (buf, seqid) => {
    connection.write(buf, seqid);
  };
  const transport = new connection.transport(undefined, writeCb);
  const client = new ServiceClient(transport, connection.protocol);
  transport.client = client;
  connection.client = client;
  return client;
};
var lineClient = (path, authToken = null) => {
  const header = {
    "X-Line-Application": Constant.LINE.APPLICATION_IDENTITY
  };
  if (authToken !== null) {
    header["X-Line-Access"] = authToken;
  }
  const host = Constant.httpUrlWrapper(Constant.LINE.HOST, null, true);
  const port = Constant.USE_HTTPS ? 443 : 80;
  const opts = {
    transport: import_thrift.default.TBufferedTransport,
    protocol: import_thrift.default.TCompactProtocol,
    headers: header,
    https: Constant.USE_HTTPS,
    path,
    useCORS: true
  };
  const connection = new FetchConnection(host, port, opts);
  const client = createFetchClient(exports_TalkService, connection);
  connection.on("error", (err) => {
    console.error("FetchConnection error:", err);
  });
  return client;
};
var client_default = lineClient;

// app/client/worker.ts
globalThis.Buffer = Buffer2;
var sw = self;
var isPolling = false;
var revision = 0;
var token = "";
var userIdHash = "";
var pollClient = null;
var idbInstance = null;
var opController = null;
var swSystem = null;
sw.addEventListener("install", (event) => {
  event.waitUntil(sw.skipWaiting());
});
sw.addEventListener("activate", (event) => {
  event.waitUntil(sw.clients.claim());
});
sw.addEventListener("message", async (event) => {
  const data = event.data;
  if (!data)
    return;
  switch (data.type) {
    case "INIT_POLL":
      token = data.token;
      revision = data.revision;
      userIdHash = data.userIdHash;
      console.log("SW: INIT_POLL received", { revision, userIdHash });
      swSystem = {
        profile: {
          userId: "",
          userIdHash,
          displayName: "",
          picturePath: "",
          statusMessage: ""
        },
        clients: {
          query: client_default(const_default.LINE.PATH.QUERY, token)
        },
        idb: null,
        sync: {
          syncProfile(profile) {
            swSystem.profile.userId = profile.mid;
            swSystem.profile.userIdHash = userIdHash;
            swSystem.profile.displayName = profile.displayName;
            swSystem.profile.picturePath = profile.picturePath;
            swSystem.profile.statusMessage = profile.statusMessage;
          }
        },
        chatBoxAddMsg: null,
        chatBoxReadMsg: null
      };
      idbInstance = new idb_default(swSystem);
      idbInstance.updateUserIdHash(userIdHash);
      await idbInstance.init();
      swSystem.idb = idbInstance;
      opController = new operation_default(swSystem);
      pollClient = client_default(const_default.LINE.PATH.POLL, token);
      isPolling = true;
      pollLoop();
      break;
    case "STOP_POLL":
      console.log("SW: STOP_POLL received");
      isPolling = false;
      break;
    case "UPDATE_REVISION":
      console.log("SW: UPDATE_REVISION received", data.revision);
      revision = Math.max(revision, data.revision);
      break;
  }
});
async function pollLoop() {
  console.log("SW: Polling loop started at revision", revision);
  while (isPolling) {
    try {
      const ops = await new Promise((resolve, reject) => {
        pollClient.fetchOperations(revision, const_default.FETCH_OP_NUM, (err, result) => {
          if (err)
            return reject(err);
          resolve(result);
        });
      });
      if (!isPolling)
        break;
      if (ops && ops.length > 0) {
        console.log(`SW: Fetched ${ops.length} operations`);
        for (const op of ops) {
          if (op.revision) {
            const opRev = typeof op.revision === "object" && op.revision.toNumber ? op.revision.toNumber() : parseInt(op.revision, 10);
            if (opRev > revision) {
              revision = opRev;
            }
          }
          if (opController) {
            await opController.update(op);
          }
        }
        if (idbInstance && idbInstance.user) {
          await idbInstance.user.put(const_default.IDB.USER.SETTINGS, {
            id: const_default.IDB.USER.KEY.SETTINGS_REVISION,
            value: revision.toString()
          });
        }
        const clientsList = await sw.clients.matchAll({ type: "window" });
        for (const c of clientsList) {
          c.postMessage({
            type: "POLL_OPERATIONS",
            operations: ops,
            revision
          });
        }
      }
    } catch (err) {
      console.error("SW: Polling error occurred", err);
      const clientsList = await sw.clients.matchAll({ type: "window" });
      for (const c of clientsList) {
        c.postMessage({
          type: "POLL_ERROR",
          error: err.message || err
        });
      }
      await new Promise((resolve) => setTimeout(resolve, const_default.TIMEOUT.RETRY * 1000));
    }
  }
  console.log("SW: Polling loop stopped");
}
